mapper.select:
SELECT
    (
        SELECT t.id
        FROM app_generation_task t
        WHERE t.conversation_id = #{conversationId}
          AND t.client_message_id = #{clientMessageId}
          AND t.deleted_at IS NULL
        ORDER BY t.id DESC
        LIMIT 1
    ) AS generation_task_id,
    c.character_id
FROM app_conversation c
WHERE c.id = #{conversationId}
